<?php
require_once __DIR__ . '/../includes/permissions.php';
require_role('admin');
$pdo=db();
$filters=['period'=>(int)($_GET['period']??0),'department'=>(int)($_GET['department']??0),'teacher'=>(int)($_GET['teacher']??0),'subject'=>(int)($_GET['subject']??0),'class'=>(int)($_GET['class']??0)];
$periods=$pdo->query('SELECT id,name FROM evaluation_periods ORDER BY starts_at DESC')->fetchAll();
$departments=$pdo->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();
$teachers=$pdo->query('SELECT t.id,u.full_name FROM teachers t JOIN users u ON u.id=t.user_id ORDER BY u.full_name')->fetchAll();
$subjects=$pdo->query('SELECT id,code,name FROM subjects ORDER BY name')->fetchAll();
$classes=$pdo->query('SELECT id,name,school_year FROM classes ORDER BY school_year DESC,name')->fetchAll();
$where=[];$params=[];
foreach(['period'=>'e.period_id','department'=>'u.department_id','teacher'=>'e.teacher_id','subject'=>'e.subject_id','class'=>'e.class_id'] as $key=>$column){if($filters[$key]>0){$where[]="$column = ?";$params[]=$filters[$key];}}
$sql="SELECT e.id,e.submitted_at,p.name period_name,d.name department,u.full_name teacher_name,s.code subject_code,s.name subject_name,c.name class_name,c.school_year,COUNT(DISTINCT a.id) rating_answers,ROUND(AVG(a.rating_value),2) average FROM evaluations e JOIN evaluation_periods p ON p.id=e.period_id JOIN teachers t ON t.id=e.teacher_id JOIN users u ON u.id=t.user_id LEFT JOIN departments d ON d.id=u.department_id JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id LEFT JOIN evaluation_answers a ON a.evaluation_id=e.id AND a.rating_value IS NOT NULL";
if($where)$sql.=' WHERE '.implode(' AND ',$where);
$sql.=' GROUP BY e.id,e.submitted_at,p.name,d.name,u.full_name,s.code,s.name,c.name,c.school_year ORDER BY e.submitted_at DESC LIMIT 1000';
$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
if(isset($_GET['export']) && $_GET['export']==='csv'){
    audit('export','reports',null,['filters'=>$filters]);
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="evaluation-report-'.date('Y-m-d').'.csv"');
    $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Period','Department','Teacher','Subject code','Subject','Class','School year','Responses','Average','Submitted']);
    foreach($rows as $r){$line=[$r['period_name'],$r['department'],$r['teacher_name'],$r['subject_code'],$r['subject_name'],$r['class_name'],$r['school_year'],1,$r['average'],$r['submitted_at']];foreach($line as &$value){if(is_string($value)&&preg_match('/^[=+@\-\t\r]/',$value))$value="'".$value;}unset($value);fputcsv($out,$line);}fclose($out);exit;
}
$responseCount=count($rows);$avg=null;if($responseCount){$sum=0;$n=0;foreach($rows as $r){if($r['average']!==null){$sum+=(float)$r['average'];$n++;}}$avg=$n?number_format($sum/$n,2):null;}
$pageTitle='Reports';require __DIR__.'/../includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">INSIGHTS & REPORTS</div><h1>Evaluation results</h1><p>Filter submitted evaluations by academic term, department, teacher, subject, or class.</p></div><a class="button button-quiet" href="<?= e(url('admin/reports.php?'.http_build_query(array_merge($_GET,['export'=>'csv'])))) ?>">↓ Export CSV</a></div>
<form class="panel filter-panel" method="get"><label>Period<select name="period"><option value="0">All periods</option><?php foreach($periods as $o): ?><option value="<?= (int)$o['id'] ?>" <?= $filters['period']===(int)$o['id']?'selected':'' ?>><?= e($o['name']) ?></option><?php endforeach; ?></select></label><label>Department<select name="department"><option value="0">All departments</option><?php foreach($departments as $o): ?><option value="<?= (int)$o['id'] ?>" <?= $filters['department']===(int)$o['id']?'selected':'' ?>><?= e($o['name']) ?></option><?php endforeach; ?></select></label><label>Teacher<select name="teacher"><option value="0">All teachers</option><?php foreach($teachers as $o): ?><option value="<?= (int)$o['id'] ?>" <?= $filters['teacher']===(int)$o['id']?'selected':'' ?>><?= e($o['full_name']) ?></option><?php endforeach; ?></select></label><label>Subject<select name="subject"><option value="0">All subjects</option><?php foreach($subjects as $o): ?><option value="<?= (int)$o['id'] ?>" <?= $filters['subject']===(int)$o['id']?'selected':'' ?>><?= e($o['code'].' · '.$o['name']) ?></option><?php endforeach; ?></select></label><label>Class<select name="class"><option value="0">All classes</option><?php foreach($classes as $o): ?><option value="<?= (int)$o['id'] ?>" <?= $filters['class']===(int)$o['id']?'selected':'' ?>><?= e($o['name'].' · '.$o['school_year']) ?></option><?php endforeach; ?></select></label><button class="button button-primary">Apply filters</button></form>
<div class="stats-grid stats-three"><article class="stat-card"><span class="stat-label">Matched evaluations</span><strong><?= $responseCount ?></strong></article><article class="stat-card"><span class="stat-label">Mean evaluation average</span><strong><?= e($avg??'—') ?><small class="out-of"> / 5</small></strong></article><article class="stat-card"><span class="stat-label">Data privacy</span><strong class="privacy-stat">✓</strong><span class="stat-caption">No student names are included</span></article></div>
<section class="panel"><div class="panel-heading"><div><div class="eyebrow">SUBMISSIONS</div><h2>Matching evaluations</h2></div><span class="pill pill-muted">Up to 1,000 latest</span></div><div class="table-wrap"><table><thead><tr><th>Period</th><th>Teacher</th><th>Subject</th><th>Class</th><th>Answers</th><th>Average</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['period_name']) ?></td><td><?= e($r['teacher_name']) ?><small><?= e($r['department']??'') ?></small></td><td><?= e($r['subject_code'].' · '.$r['subject_name']) ?></td><td><?= e($r['class_name']) ?><small><?= e($r['school_year']) ?></small></td><td><?= (int)$r['rating_answers'] ?></td><td><?= e(format_average($r['average'])) ?></td><td><?= e(date('M j, Y',strtotime($r['submitted_at']))) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="table-empty">No evaluations match these filters.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>